/// <summary>
/// Finds the specified instance of the <c>SysFileStoreParameters</c> record if it exists; otherwise,
/// creates and returns a new record.
/// </summary>
/// <param name="_forupdate">
/// A Boolean value that specifies whether to select the record for update; optional.
/// </param>
/// <returns>
/// The single instance of the record.
/// </returns>
static AAXSysFileStoreParametersValues find(RecId _AAXSystemParametersVersionRecId,boolean _forupdate = false)
{
    AAXSysFileStoreParametersValues parameter;

    if (_forupdate)
    {
        parameter.selectForUpdate(_forupdate);
    }

    select firstonly RecId from parameter
        where parameter.AAXSystemParametersVersion == _AAXSystemParametersVersionRecId;

    if (!parameter && !parameter.isTmp())
    {
        Company::createParameter(parameter);
    }

    return parameter;
}

public static void createDefault(RecId _AAXSystemParametersVersionRecId)
{
    AAXSysFileStoreParametersValues AAXSysFileStoreParametersValues;
    SysFileStoreParameters SysFileStoreParameters;

    if(!AAXSysFileStoreParametersValues::exists(_AAXSystemParametersVersionRecId))
    {
        SysFileStoreParameters = SysFileStoreParameters::find();

        AAXSysFileStoreParametersValues.AAXSystemParametersVersion = _AAXSystemParametersVersionRecId;
        AAXSysFileStoreParametersValues.FilePath = SysFileStoreParameters.FilePath;
        AAXSysFileStoreParametersValues.insert();
    }
}
